[hidden] { display: none !important; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; background: #101923; color: #f3f5ec; }
* { box-sizing: border-box; }
body { min-width: 320px; min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #203541 0, #101923 65%); font-size: 16px; }
.booking-card { width: min(100%, 480px); padding: 32px; border: 1px solid #344850; border-radius: 20px; background: #18252d; box-shadow: 0 24px 70px #080e13a8; }
.header { text-align: center; margin-bottom: 28px; }
.eyebrow { color: #f2b84b; font-size: 14px; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 10px 0 8px; font-size: clamp(28px, 7vw, 36px); line-height: 1.1; }
.header p { margin: 0; color: #b9c5c7; }
.bus { padding: 20px; border: 1px solid #40565c; border-radius: 18px 18px 28px 28px; background: #202f37; }
.driver { display: flex; justify-content: space-between; align-items: center; margin: 0 0 18px; padding: 0 4px 12px; border-bottom: 1px dashed #587078; color: #9cabad; font-size: 13px; font-weight: 700; letter-spacing: .12em; }
.wheel { color: #f2b84b; font-size: 24px; }
.seat-grid { display: grid; grid-template-columns: 1fr 1fr 22px 1fr 1fr; gap: 9px 7px; }
.seat { min-height: 40px; border: 1px solid #789090; border-radius: 10px 10px 7px 7px; background: #31464b; color: #f3f5ec; font: inherit; font-size: 14px; font-weight: 700; cursor: pointer; transition: background .15s, transform .15s, border-color .15s; }
.seat:hover:not(:disabled) { border-color: #f2b84b; background: #40595b; }
.seat:active:not(:disabled) { transform: scale(.95); }
.seat:focus-visible { outline: 3px solid #f2b84b; outline-offset: 3px; }
.seat.selected { border-color: #f2b84b; background: #f2b84b; color: #17232b; }
.seat:disabled { border-color: #485356; background: #394247; color: #929b9b; cursor: not-allowed; text-decoration: line-through; }
.aisle { display: grid; place-items: center; color: #778b8d; font-size: 11px; writing-mode: vertical-rl; letter-spacing: .1em; }
.legend { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; margin-top: 22px; color: #c4cecb; font-size: 14px; }
.legend span { display: inline-flex; align-items: center; gap: 7px; }
.key { width: 13px; height: 13px; border-radius: 4px; background: #31464b; border: 1px solid #789090; }
.key.selected { background: #f2b84b; border-color: #f2b84b; }
.key.booked { background: #394247; border-color: #485356; }
.summary { margin-top: 24px; padding: 18px; border-radius: 14px; background: #101a20; }
.summary-row { display: flex; justify-content: space-between; gap: 12px; padding: 5px 0; color: #b9c5c7; }
.summary-row strong { color: #f3f5ec; text-align: right; }
#price::before { content: '¢'; color: #f2b84b; }
.discount-note { margin: 10px 0 0; color: #f2b84b; font-size: 14px; }
.status { min-height: 20px; margin: 12px 0 0; color: #f2b84b; text-align: center; font-size: 14px; }
@media (max-width: 400px) { body { padding: 18px 12px; } .booking-card { padding: 22px 16px; } .bus { padding: 15px 12px; } .seat-grid { gap: 8px 5px; } .seat { min-height: 42px; font-size: 13px; } .aisle { font-size: 10px; } }

const grid = document.querySelector('#seat-grid');
const chosenSeats = document.querySelector('#chosen-seats');
const priceDisplay = document.querySelector('#price');
const discountNote = document.querySelector('#discount-note');
const status = document.querySelector('#status');
const booked = new Set(['1B', '3D', '5A', '7C', '9B']);
const selected = new Set();

function updateSummary() {
  const seats = [...selected].sort((a, b) => {
    const [, rowA, colA] = a.match(/(\d+)([A-D])/);
    const [, rowB, colB] = b.match(/(\d+)([A-D])/);
    return Number(rowA) - Number(rowB) || colA.localeCompare(colB);
  });
  chosenSeats.textContent = seats.length ? seats.join(', ') : 'None';
  const total = seats.length * 12 * (seats.length === 4 ? 0.9 : 1);
  priceDisplay.textContent = String(Number(total.toFixed(2)));
  discountNote.hidden = seats.length !== 4;
}

for (let row = 1; row <= 10; row++) {
  for (let col = 0; col < 5; col++) {
    const cell = document.createElement(col === 2 ? 'span' : 'button');
    if (col === 2) {
      cell.className = 'aisle';
      cell.setAttribute('aria-hidden', 'true');
      cell.textContent = 'AISLE';
    } else {
      const letter = String.fromCharCode(65 + (col > 2 ? col - 1 : col));
      const code = `${row}${letter}`;
      cell.type = 'button';
      cell.className = 'seat';
      cell.textContent = code;
      cell.setAttribute('aria-label', booked.has(code) ? `Seat ${code}, booked` : `Seat ${code}, available`);
      if (booked.has(code)) {
        cell.disabled = true;
        cell.setAttribute('aria-pressed', 'false');
        cell.title = 'Already booked';
      } else {
        cell.setAttribute('aria-pressed', 'false');
        cell.addEventListener('click', () => {
          if (selected.has(code)) {
            selected.delete(code);
            cell.classList.remove('selected');
            cell.setAttribute('aria-pressed', 'false');
            status.textContent = `Seat ${code} removed.`;
          } else if (selected.size < 4) {
            selected.add(code);
            cell.classList.add('selected');
            cell.setAttribute('aria-pressed', 'true');
            status.textContent = `Seat ${code} selected.`;
          } else {
            status.textContent = 'You can select up to four seats.';
          }
          updateSummary();
        });
      }
    }
    grid.append(cell);
  }
}
updateSummary();
